# name: perfect_alternation_choice_rate
# description: Proportion of choices for a perfectly alternating sequence (HTHT.../THTH..., length>=4) when paired with a non-alternating one; observed above null_mean means the model over-penalises perfect alternation (people find it more random than predicted), below means it under-penalises it.
def test_statistic(df):
    a = df["sequence_a"].astype(str); b = df["sequence_b"].astype(str)
    def alt(s):
        n = s.str.len()
        p1 = s.str.match(r"^(HT)*H?$"); p2 = s.str.match(r"^(TH)*T?$")
        return (p1 | p2) & (n >= 4)
    aa, ab = alt(a), alt(b)
    m = aa ^ ab
    if m.sum() == 0:
        return 0.5
    chose_alt = np.where(aa[m], df["chose_left"][m], 1 - df["chose_left"][m])
    return float(np.mean(chose_alt))

# name: longest_run_avoidance_equal_switches
# description: Among pairs whose switch counts differ by at most 1 but whose longest runs differ, the proportion of choices for the sequence with the shorter longest run; observed above null_mean means people penalise long streaks beyond what switch/motif statistics explain (model under-penalises streaks), below means over-penalises.
def test_statistic(df):
    a = df["sequence_a"].astype(str); b = df["sequence_b"].astype(str)
    def switches(s):
        return s.str.count(r"(?=HT)|(?=TH)")
    def longest(s):
        return s.str.findall(r"H+|T+").map(lambda L: max(len(x) for x in L))
    ka, kb = switches(a), switches(b)
    la, lb = longest(a), longest(b)
    m = ((ka - kb).abs() <= 1) & (la != lb)
    if m.sum() == 0:
        return 0.5
    a_short = (la < lb)[m].to_numpy()
    y = df["chose_left"][m].to_numpy()
    return float(np.mean(np.where(a_short, y, 1 - y)))

# name: participant_left_rate_sd
# description: Standard deviation across participants of each participant's proportion of Left choices; observed above null_mean means people have individual side biases that the model (no side-bias term) under-produces, below means less spread than predicted.
def test_statistic(df):
    return float(df.groupby("participant_id")["chose_left"].mean().std(ddof=0))

# name: balance_preference_similar_switches
# description: Among pairs whose switch counts differ by at most 1 and whose head-count imbalances |#H - n/2| differ, the proportion of choices for the more balanced sequence; observed above null_mean means people weight H/T balance more than the model implies, below means less.
def test_statistic(df):
    a = df["sequence_a"].astype(str); b = df["sequence_b"].astype(str)
    def switches(s):
        return s.str.count(r"(?=HT)|(?=TH)")
    ka, kb = switches(a), switches(b)
    n = a.str.len()
    ia = (a.str.count("H") - n / 2).abs(); ib = (b.str.count("H") - n / 2).abs()
    m = ((ka - kb).abs() <= 1) & (ia != ib)
    if m.sum() == 0:
        return 0.5
    a_bal = (ia < ib)[m].to_numpy()
    y = df["chose_left"][m].to_numpy()
    return float(np.mean(np.where(a_bal, y, 1 - y)))

# name: response_side_repeat_rate
# description: Proportion of consecutive trials (within participant, ordered by trial_index) on which the participant pressed the same side as on the previous trial; observed above null_mean means response perseveration the model (trial-independent) lacks, below means more side alternation than predicted.
def test_statistic(df):
    d = df.sort_values(["participant_id", "trial_index"])
    y = d["chose_left"].to_numpy(); p = d["participant_id"].to_numpy()
    same_p = p[1:] == p[:-1]
    if same_p.sum() == 0:
        return 0.5
    return float(np.mean((y[1:] == y[:-1])[same_p]))
